import { ReplicatedStorage } from "@rbxts/services";
import type * as ZapServer from "./zapServer";

/**
 * Typed handle to the Zap-generated server module. The `.d.ts` is generated by
 * `npm run zap` (see net.zap), so the types can never drift from the contract.
 */
const module = ReplicatedStorage.WaitForChild("Network").WaitForChild("Server") as ModuleScript;
// eslint-disable-next-line @typescript-eslint/no-require-imports -- Zap output is a plain ModuleScript
export const ServerNet = require(module) as typeof ZapServer;
